import sys
import contextlib

@contextlib.contextmanager
def redirected_io():
    sys.stdin = open(0)
    sys.stdout = open(1, 'w')
    try:
        yield
    finally:
        sys.stdin.close()
        sys.stdout.close()

def num1(n):
